public String format(LoggingEvent event) {
    // Check if the event is null
    if (event == null) {
        throw new IllegalArgumentException("Event cannot be null");
    }

    // Create a StringBuilder to build the formatted string
    StringBuilder formattedString = new StringBuilder();

    // Append the date and time
    formattedString.append(event.getMillis() / 1000L);
    formattedString.append(" ");

    // Append the (time) tag
    formattedString.append('(');

    // Append the date
    formattedString.append(event.getMillis() / 1000L);
    formattedString.append(' ');

    // Append the time (with seconds)
    formattedString.append(((event.getMillis() % 1000L) / 100L));
    formattedString.append(":");

    // Append the time (with tens of seconds)
    formattedString.append(((event.getMillis() % 1000L) % 100L) / 10L);
    formattedString.append(":");

    // Append the time (with hundredths of seconds)
    formattedString.append((event.getMillis() % 1000L) % 10L);

    formattedString.append(")');

    // Append the thread ID
    formattedString.append(event.getThreadName());

    formattedString.append(' ');

    // Append the level
    String level = event.getLevel().toString();
    if (level.length() > 4) {
        level = level.substring(1); // Remove the "Level" prefix
    }
    formattedString.append(level);

    formattedString.append(' ');

    // Append the message
    formattedString.append(event.getMessage().toString());

    // Append the throwable
    Throwable throwable = event.getThrowable();
    if (throwable != null) {
        formattedString.append('\n');
        formattedString.append(throwable.getMessage());
        formattedString.append('\n');
        // Add the stack trace if needed
        if (event.getThrowable() instanceof org.apache.log4j.NestedThrowable) {
            formattedString.append((org.apache.log4j.NestedThrowable) event.getThrowable()).getNestedThrowable().toString();
        }
    }

    return formattedString.toString();
}

public String format(LoggingEvent event) {
    // Check if the event is null
    if (event == null) {
