    String message = event.getMessage().getMessage();

    // Define the conversion pattern
    String pattern = "%d{yyyy-MM-dd HH:mm:ss} %-5level [%thread] - %msg%n";

    // Create a new ByteBuffer initialized with the conversion pattern
    ByteBuffer buffer = ByteBuffer.allocate(pattern.length());

    // Format the log level into the ByteBuffer at position 0
    buffer.put(pattern.getBytes().get(0, 5), 0);

    // Format the timestamp into the ByteBuffer at position 5
    buffer.putBytes(timestamp).putChar(' ');

    // Append the thread name to the ByteBuffer
    buffer.append(Thread.currentThread().getName()).append(' ');

    // Format the message into the ByteBuffer at position n where n is the size of the message plus 1
    byte[] messageBytes = message.getBytes();
    buffer.putBytes(messageBytes, 0, messageBytes.length + 1);

    // Position the ByteBuffer at the end of the formatted string
    buffer.flip();

    // Convert the ByteBuffer to a string and return it
    return buffer.toString();
}

