public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    if (graph == null) {
        throw new IllegalArgumentException("Input graph cannot be null.");
    }

    // Create a mapping where every vertex maps to itself
    Map<V, V> mapping = new HashMap<>();
    for (V vertex : graph.vertexSet()) {
        mapping.put(vertex, vertex);
    }

    // Check the mapping for any inconsistencies
    for (V vertex : graph.vertexSet()) {
        if (!mapping.containsKey(vertex) || mapping.get(vertex) != vertex) {
            throw new IllegalStateException("Mapping incomplete or not consistent.");
        }
    }

    // Create a new isomorphic graph mapping
    return new IsomorphicGraphMapping<>(graph, mapping);
}

