public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    buffer.putInt32Le(size);
    out.write(buffer.currentBuffer().array(), buffer.currentOffset());
    buffer.advance(size);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Start by encoding the length of the message and writing it to the OutputStream
    int lengthCode = schema.length();
    out.write((byte) lengthCode);

    // Shift the data to the left by the length of the length code (0, 8, 16, 24, 32, 40, 48, 56, 64)
    byte[] data = schema.encode(message);
    if (lengthCode != 0) {
        out.write(shiftBytes(data, lengthCode));
    } else {
        out.write(data);
    }

    // Write the shifted data back into the LinkedBuffer if it's not null
    if (buffer != null) {
        buffer.addBytes(data);
    }

    // Return the total size of the message including the length code
    return data.length + 1;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Assuming Schema has a write function to serialize the message
    schema.write(out, message, buffer);

    // Calculate and write the length of the serialized message
    out.write(buffer.length);
    return buffer.length;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throwsIOException {
    int messageSize = schema.calculateMessageSize(message);
    buffer.appendVarInt(messageSize);
    schema.write(out, message);
    return messageSize;
}

public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int messageSize = schema.getSerializedSize(message);
    out.write((byte) (messageSize >>> 24)); // MSB of size
    out.write((byte) (messageSize >>> 16)); // Second MSB of size
    out.write((byte) (messageSize >>> 8));  // Third MSB of size
    out.write((byte) (messageSize >>> 0));  // LSB of size
    schema.serializedWrite(out, message, buffer);
    return messageSize + buffer.size();
}

