public long readLong(final int offset) {
    // Ensure the offset is within valid bounds
    if (offset < 0 || offset >= data.length) {
        throw new IndexOutOfBoundsException("Offset is out of bounds.");
    }

    // Use readInt method to read two 32-bit integers
    long low = readInt(offset);
    long high = readInt(offset + 4);

    // Combine the low and high parts to form the 64-bit long
    return high << 32 | low;
}

public long readLong(final int offset) {
    // Check if the offset is within the bounds of the data array
    if (offset + 8 > this.data.length) {
        throw new IllegalArgumentException("Offset out of bounds");
    }

    // Convert the bytes read from the data array to a signed long
    long value = 0;
    for (int i = 0; i < 8; i++) {
        value <<= 8;
        value |= this.data[offset + i];
    }

    return value;
}

