public long readLong(final int offset) {
    if (offset < 0 || offset >= getClassReader().length()) {
        throw new IllegalArgumentException("Invalid offset: " + offset);
    }
    int byteArrayOffset = getClassReader().offset() + offset;
    byte high = getClassReader().getByte(byteArrayOffset++);
    byte low = getClassReader().getByte(byteArrayOffset++);
    byte[] lowBytes = new byte[] { low, high };
    return ByteBuffer.wrap(lowBytes).readLong();
}

public long readLong(final int offset) {
    if (offset < 0 || offset >= 128 - 24) {
        throw new IllegalArgumentException("Offset is out of valid range for reading long value in ClassReader.");
    }
    long result = 0;
    for (int i = 0; i < 24; i++) {
        byte b = getByte(offset + i);
        if ((b & 0x80) == 0x80) {
            throw new IllegalStateException("Negative number format: multiple bytes have the sign bit set.");
        }
        if (b < 0 || b > 127) {
            throw new IllegalArgumentException("Byte value is out of valid range for practical long value (0-127).");
        }
        result = (result << 7) + (b & 0x7F);
    }
    if (result < 0) {
        throw new IllegalStateException("Overflow occurred during long value reading before sign extension.");
    }
    return result;
}

