protected List<TimeRange> buildTimeRanges(long start, long end) {
        // Ensure the start time is smaller than the end time
        if (start >= end) {
            throw new IllegalArgumentException("Start time must be less than end time");
        }

        List<TimeRange> result = new ArrayList<>();
        long duration = end - start;
        while (duration > FETCH_DATA_DURATION) {
            // Split the current range into two parts and add the first part to the result
            TimeRange range1 = new TimeRange(start, start + FETCH_DATA_DURATION);
            result.add(range1);
            // Calculate the new start time for the next range
            start += FETCH_DATA_DURATION;
            // Update the remaining duration
            duration = end - start;
        }
        // If there is any remaining data after the last split
        if (duration > 0) {
            TimeRange remainingRange = new TimeRange(start, end);
            result.add(remainingRange);
        }

        return result;
    }

