protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Check if start and end are valid
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Both start and end times must be non-negative.");
    }

    // Calculate the duration between start and end
    long duration = end - start;

    // Check if duration is larger than FETCH_DATA_DURATION
    long fetchDataDuration = 1800; // Example duration in seconds
    if (duration > fetchDataDuration) {
        // Split time ranges
        int splitCount = (int) Math.ceil(duration / fetchDataDuration);
        long gap = duration / splitCount;

        List<TimeRange> timeRanges = new ArrayList<>();
        long currentStart = start;
        for (int i = 0; i < splitCount; i++) {
            long currentEnd = currentStart + fetchDataDuration;
            timeRanges.add(new TimeRange(currentStart, currentEnd));
            currentStart = currentEnd + gap;
        }

        return timeRanges;
    } else {
        // If duration is within FETCH_DATA_DURATION, return a single time range
        return List.of(new TimeRange(start, end));
    }
}

