protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start >= end) {
        throw new IllegalArgumentException("Start time must be less than end time.");
    }

    long duration = end - start;
    if (duration >= FETCH_DATA_DURATION) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long endTime = start;
        while (endTime < end) {
            long nextEndTime = Math.min(endTime + FETCH_DATA_DURATION - 1, end);
            timeRanges.add(new TimeRange(endTime, nextEndTime));
            endTime = nextEndTime + 1;
        }
        return timeRanges;
    } else {
        return List.of(new TimeRange(start, end));
    }
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();

        if (start >= end) {
            throw new IllegalArgumentException("Start time must be less than start time");
        }

        LocalDateTime startLocalDateTime = LocalDateTime.ofEpochSecond(start / 1000, 0, LocalDateTime.ZONE_ID.systemDefault());
        LocalDateTime endLocalDateTime = LocalDateTime.ofEpochSecond(end / 1000, 0, LocalDateTime.ZONE_ID.systemDefault());

        long effectiveDuration = Duration.between(startLocalDateTime, endLocalDateTime).getSeconds();

        if (effectiveDuration >= FETCH_DATA_DURATION.getSeconds()) {
            throw new IllegalArgumentException("Range exceeds data fetching duration");
        }

        timeRanges.add(new TimeRange(startLocalDateTime, startLocalDateTime.plusSeconds(FETCH_DATA_DURATION.getSeconds())));
        timeRanges.add(new TimeRange(startLocalDateTime.plusSeconds(FETCH_DATA_DURATION.getSeconds()), endLocalDateTime));

        return Collections.unmodifiableList(timeRanges);
    }

