protected List<TimeRange> buildTimeRanges(long start, long end) {
        if (start < 0 || end < 0 || start > end) {
            throw new IllegalArgumentException("Start and end times must be non-negative and start must be less than or equal to end.");
        }

        List<TimeRange> timeRanges = new ArrayList<>();

        long currentStart = start;
        long currentEnd = Math.min(end, start + FETCH_DATA_DURATION);

        while (currentStart <= currentEnd) {
            timeRanges.add(new TimeRange(currentStart, currentEnd));
            currentStart = currentEnd + 1;
        }

        return timeRanges;
