public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket == 0 || dayStep < 1) {
        throw new IllegalArgumentException("timeBucket must be greater than 0 and dayStep must be greater than 0");
    }

    int realYear = 1970 + ((timeBucket / (1000 * 60 * 60 * 24 * 365)) % 365);
    long cmSec = (timeBucket / (1000 * 60 * 60 * 24 * 365)) * 1000 * 60 * 60 * 24;
    int compTimeBucket = cmSec / (dayStep * 24 * 60 * 60);

    // If compTimeBucket is not accepted (i.e., it belongs to the next year)
    if (compTimeBucket > 365 + realYear || compTimeBucket < (realYear * 365)) {
        // Round compTimeBucket to the nearest valid day (~end of the year ~ start of the year)
        compTimeBucket = (realYear * 365) - compTimeBucket + 1;
    }

    // Return the compressed time bucket in YYYYMMDD format
    return (long) (realYear + (compTimeBucket - 1) / 365);
}

