public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || index < 0 || index >= str.length() || len < 0) {
        throw new IllegalArgumentException("Invalid input values.");
    }
    if (index + len > str.length()) {
        throw new IndexOutOfBoundsException("Index plus length exceeds the string length.");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        int c = str.charAt(i);
        if ((c & 0x80) == 0) {
            size++;
        } else if (c >= 0xC0 && c <= 0xDF) {
            size += 2;
        } else if (c >= 0xE0 && c <= 0xEF) {
            size += 3;
        } else if (c >= 0xF0 && c <= 0xF7) {
            size += 4;
        }
    }
    return size;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    if (str == null || index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid input: str = " + str + ", index = " + index + ", len = " + len);
    }

    int size = 0;
    int i = index;

    while (i < index + len) {
        int prev = size;
        int c = str.charAt(i);
        size += 1;

        if (c >= 0x80) {
            if ((c & 0xe0) == 0xc0) {
                size += 1;
            } else if ((c & 0xf0) == 0xe0) {
                size += 1;
            } else if ((c & 0xf8) == 0xf0) {
                size += 1;
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 sequence: " + str.charAt(i));
            }
        }

        if (prev != size) {
            i++;
        }
    }

    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || str.length() <= index || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid input: str is null and/or index or len exceed the length of str.");
    }

    int size = 0;
    int initialLength = len;
    while (len > 0) {
        int next = str.charAt(index++) & 0xFF;
        size++;

        if ((next & 0x80) == 0) {
            continue;
        } else if ((next & 0xE0) == 0xC0) {
            next = next & 0x1F;
            size++;
        } else if ((next & 0xF0) == 0xE0) {
            next = next & 0xF;
            size++;
        } else if ((next & 0xF8) == 0xF0) {
            next = next & 0x3;
            size++;
        } else if ((next & 0xFC) == 0xF8) {
            next = next & 0x1;
            size++;
        }
    }

    return size >= 0 && size <= initialLength ? size : -1;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
