    while (i < index + len) {
        int b = str.charAt(i);

        if ((b & 0xC0) == 0x80) {
            b = str.charAt(i + 1);
            if ((b & 0xC0) == 0x80) b = str.charAt(i + 2);
        }

        size++;
        i++;
    }

    return size;
}

