    while (i < len + index) {
        int b = str.charAt(i);
        if ((b & 0xE0) == 0xC0) {
            size += 2;
            i++;
        } else if ((b & 0xF8) == 0xF0) {
            size += 3;
            i += 2;
        } else if ((b & 0xFC) == 0xFC) {
            size += 4;
            i += 3;
        } else {
            size += 1;
        }
        i++;
    }

    return size;
}

