            String paramName = matcher.group(i).substring(1);
            String paramValue = request.getParameter(paramName);
            parameters.put(paramName, paramValue);
        }
    }

    String requestCycleTemplate = request.getServletContext().getInitParameter("http.servlet.request_volume_per_template");
    if (requestCycleTemplate == null) {
        requestCycleTemplate = "default";
    }

    String requestSession = request.getServletContext().getInitParameter("http.servlet.request_volume_per_session");
    if (requestSession == null) {
        requestSession = "default";
    }

    return new AtmosphereRequest(requestURI, pathVariables, parameters, requestCycleTemplate, requestSession);
}

