    }

    StringBuilder sb = new StringBuilder();
    sb.append("{");
    convertToJSON(features, sb);
    sb.append("}");
    return sb.toString();
}

private void convertToJSON(JSONWriter.Feature[] features, StringBuilder sb) {
    for (JSONWriter.Feature feature : features) {
        if (sb.length() > 1) {
            sb.append(",");
        }
        switch (feature) {
            case EscapeForwardSlash:
                sb.append("\"/\": true");
                break;
            case EscapeCommasInStrings:
                sb.append("\",\": true");
                break;
            case EscapeUnquotedNames:
                sb.append("\"\"\": true");
                break;
            // Handle other features as needed
            default:
                throw new IllegalArgumentException("Unsupported feature: " + feature);
        }
    }
}

