public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        throw new IllegalArgumentException("capacity must be greater than 1");
    }

    int start = Math.max(desiredCapacity, 61);
    int max = start;

    while (true) {
        int range = checkPrime(start);
        if (range != 1) {
            return Math.max(start, range * 6) + 2;
        }
        max += 10;
        if (max > Integer.MAX_VALUE - 12) {
            throw new UnsupportedOperationException("Too large for computation");
        }
        start = max - (int) (11 * Math.log10(max) / 10);
    }
}

private static int checkPrime(int num) {
    if (num <= 1) {
        return 1;
    }
    if (num <= 3) {
        return 0;
    }
    if (num % 2 == 0 || num % 3 == 0) {
        return 1;
    }
    int i = 5;
    while (i * i <= num) {
        if (num % i == 0 || num % (i + 2) == 0) {
            return 1;
        }
        i += 6;
    }
    return 0;
}

