public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null; // Edge case: null string input yields null output
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i < str.length() - 1) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case 't':
                        sb.append('\t');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case '"':
                        sb.append('"');
                        break;
                    case '\\':
                        sb.append('\\');
                        break;
                    case 'b':
                        sb.append('\b');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    default:
                        throw new IllegalArgumentException("Unrecognized escape sequence: " + c + nextChar);
                }
                i++; // Skip the next character as it has been processed
            } else {
                throw new IllegalArgumentException("Unbalanced escape sequence: " + c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

