protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        if (tour == null || graph == null || tour.isEmpty()) {
            throw new IllegalArgumentException("Invalid input: tour or graph is null or empty");
        }

        Map<E, Integer> faceMapping = new HashMap<>();
        int currentFaceId = 0;
        GraphPath<V, E> result = new GraphPath<>();

        for (E edge : tour) {
            V source = graph.source(edge);
            V destination = graph.destination(edge);

            Integer sourceFaceId = faceMapping.getOrDefault(source, currentFaceId++);
            Integer destinationFaceId = faceMapping.getOrDefault(destination, currentFaceId++);

            if (sourceFaceId != destinationFaceId) {
                result.addEdge(new Edge<>(source, destination));
            }

            if (!faceMapping.containsKey(source)) {
                faceMapping.put(source, currentFaceId++);
            }
            if (!faceMapping.containsKey(destination)) {
                faceMapping.put(destination, currentFaceId++);
            }
        }

        return result;
    }

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    if (graph.getVertexSet().size() != tour.size()) {
        throw new IllegalArgumentException("Tour does not match vertex set size");
    }

    GraphPath<V,E> path = new GraphPath<>();

    V currentVertex = graph.getVertexSet().iterator().next();
    path.addVertex(currentVertex);

    for (E edge : tour) {
        V nextVertex = edge.getDestination();
        if (!path.hasVertex(nextVertex)) {
            path.addVertex(nextVertex);
        }
        path.addEdge(edge, graph.getEdge(edge));
        currentVertex = nextVertex;
    }

    return path;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        // Validate inputs
        if (tour == null || graph == null) {
            throw new IllegalArgumentException("Input cannot be null.");
        }

        // Create a map to store the vertices and their edges
        Map<V, Set<V>> vertexEdges = new HashMap<>();
        for (E edge : tour) {
            V source = edge.getSourceVertex();
            V destination = edge.getDestinationVertex();
            if (vertexEdges.containsKey(source)) {
                vertexEdges.get(source).add(destination);
            } else {
                vertexEdges.put(source, new HashSet<>(List.of(destination)));
            }
        }

        // Create a list to store the path
        List<V> path = new ArrayList<>();
        for (V vertex : vertexEdges.keySet()) {
            if (vertexEdges.get(vertex).contains(graph.getVertex("end"))) {
                path.clear();
                path.add(vertex);
                break;
            }
        }

        if (path.isEmpty()) {
            throw new IllegalArgumentException("No valid tour found in the set.");
        }

        // Convert the path list to a path graph
        GraphPath<V, E> graphPath = new GraphPath<>(path);
        graphPath.setGraph(graph);
        return graphPath;
    }

public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null) {
        throw new IllegalArgumentException("Tour cannot be null");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    List<V> path = new ArrayList<>();
    for (E edge : tour) {
        V start = graph.getEdgeSource(edge);
        V end = graph.getEdgeTarget(edge);
        if (path.contains(end)) {
            throw new IllegalArgumentException("Cycle detected in tour");
        }
        path.add(start);
        path.add(end);
    }

    return new GraphPath<>(path);
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Empty input set or graph
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input set and graph cannot be null.");
    }

    // Number of edges in the tour
    int edgeCount = tour.size();

    // Track a list of vertices visited during the tour
    List<V> visitedVertices = new ArrayList<>(edgeCount);

    // Start traversal from the first vertex in the tour
    V initialVertex = tour.iterator().next();
    visitedVertices.add(initialVertex);

    // Initialize the tour graph
    GraphPath<V, E> path = new DefaultGraphPath<V, E>();

    // Traverse the tour using the edges
    for (E edge : tour) {
        V sourceVertex = graph.getEdgeSource(edge);
        V targetVertex = graph.getEdgeTarget(edge);

        // Check if the target vertex has been visited before starting the traversal
        while (!visitedVertices.contains(targetVertex)) {
            // Traverse the path to find a NodeList adjacent to targetVertex
            NodeList<E> adjacentNodes = graph.getNodeListTo(targetVertex);
            if (adjacentNodes == null) {
                throw new IllegalStateException("Graph appears to be disconnected.");
            }

            // Initialize the starting edge for traversal
            E startingEdge = adjacentNodes.getNodeIter().next();

            // Add the starting edge to the tour path
            path.addAll(graph.getPath(startingEdge, targetVertex));
            visitedVertices.add(sourceVertex); // Mark the source vertex as visited
            visitedVertices.add(targetVertex); // Mark the target vertex as visited
        }
    }

    return path;
}

