            return constantPool.get(name + descriptor);
        }

        // Generate the new ID for the new item
        int id = constantPool.size() + 1;

        // Add the new item to the pool
        constantPool.put(name + descriptor, id);

        // Create a new Symbol for the new item
        Symbol newSymbol = new Symbol(id, name, descriptor);

        // Return the new symbol
        return newSymbol.getId();
    }

public int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains the same item
    if (constantPool.contains(name + ":" + descriptor)) {
        return constantPool.get(name + ":" + descriptor);
    } else {
        // Add a new Symbol with the given value and return the index
        SymInfo symInfo = new SymInfo(name, descriptor);
        constantPool.add(symInfo);
        return constantPool.indexOf(symInfo);
    }
}

public int addConstantNameAndType (String name, String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor cannot be null");
    }
    if (symbolTable.containsKey(name, descriptor)) {
        return symbolTable.get(name, descriptor).id;
    }

    Symbol newSymbol = new Symbol(name, descriptor);
    int newId = symbolsUsed counter++;
    symbolTable.put(name, descriptor, newSymbol);
    return newId;
}

public String unescapeId(String input) {
    if (input == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    StringBuilder result = new StringBuilder();
    int length = input.length();
    for (int i = 0; i < length; i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < length) {
                c = input.charAt(i + 1);
                switch (c) {
                    case '\\':
                        result.append(c);
                        break;
                    case 'n':
                        result.append('\n');
                        break;
                    case 'r':
                        result.append('\r');
                        break;
                    case '\t':
                        result.append('\t');
                        break;
                    default:
                        throw new IllegalArgumentException("Unsupported escape sequence " + c);
                }
                i++; // Skip the next character as it is escaped
            } else {
                throw new IllegalArgumentException("Escape sequence ends abruptly");
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

private String unescapeId(String input) {
    StringBuilder result = new StringBuilder();
    boolean escaped = false;

    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);

        if (c == '\\') {
            escaped = true;
            if (i + 1 < input.length() && input.charAt(i + 1) == 'N') {
                result.append("N");
                i++;
            }
        } else if (escaped) {
            switch (c) {
                case 'n':
                    result.append('\n');
                    escaped = false;
                    break;
                case 't':
                    result.append('\t');
                    escaped = false;
                    break;
                case 'r':
                    result.append('\r');
                    escaped = false;
                    break;
                case 'v':
                    result.append('\u000b');
                    escaped = false;
                    break;
                case '"':
                    result.append('"');
                    escaped = false;
                    break;
                case '\\':
                    result.append('\\');
                    escaped = false;
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escape sequence: \\'" + c + "'");
            }
        } else {
            result.append(c);
        }
    }

    return result.toString();
}

