public static String[] concatenateStringArrays(String[] array1, String[] array2) {
    // Check if both arrays are null
    if (array1 == null && array2 == null) {
        return null;
    }

    int combinedLength = array1.length + array2.length;
    String[] combinedArray = new String[combinedLength];

    int index = 0;
    // Copy elements from the first array starting from index 0
    for (int i = 0; i < array1.length && index < combinedLength; i++) {
        combinedArray[index++] = array1[i];
    }
    // Copy elements from the second array starting from index combinedLength - array2.length to index combinedLength - 1
    for (int i = 0; i < array2.length && index < combinedLength; i++) {
        combinedArray[index++] = array2[i];
    }

    return combinedArray;
}

