private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || minLabel < 0) {
        throw new IllegalArgumentException("Inputs cannot be null or invalid.");
    }

    int totalVertices = 0;
    for (Set<Integer> bucket : bucketsByLabel) {
        totalVertices += bucket.size();
    }

    if (totalVertices == 0) {
        return;
    }

    // Clear the bucket with label minLabel
    bucketsByLabel.get(minLabel).clear();
    labels.remove(minLabel);

    // Move all vertices from the bucket with label minLabel to bucket with label 0
    for (int vertex : bucketsByLabel.get(minLabel)) {
        bucketsByLabel.get(0).add(vertex);
        labels.add(vertex);
    }

    // Update the labeling
    for (int i = minLabel + 1; i < labels.size(); i++) {
        bucketsByLabel.get(i - 1).add(labels.get(i));
        labels.remove(i);
    }

    bucketsByLabel.add(0, new HashSet<>());
    labels.add(0, minLabel);
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || bucketsByLabel.size() == 0 || labels.size() == 0) {
        throw new IllegalArgumentException("Buckets, labels, or their lengths cannot be null or empty.");
    }

    int labelCount = bucketsByLabel.size();
    int firstIndex = -1;

    for (int i = 0; i < labelCount; i++) {
        if (!bucketsByLabel.get(i).isEmpty()) {
            firstIndex = i;
            break;
        }
    }

    if (firstIndex == -1) {
        return; // All buckets are empty
    }

    // Move vertices from the bucket with label minLabel to the bucket with label 0
    for (int verticesInMinLabelBucket : bucketsByLabel.get(firstIndex)) {
        labels.set(verticesInMinLabelBucket, 0);
        bucketsByLabel.set(minLabel, bucketsByLabel.get(minLabel).remove(verticesInMinLabelBucket));
        bucketsByLabel.set(0, bucketsByLabel.get(0).add(verticesInMinLabelBucket));
    }

    // Clear the bucket with label minLabel
    bucketsByLabel.set(minLabel, new HashSet<>());

    // Update labeling
    for (int i = 1; i < labelCount; i++) {
        for (int vertex : bucketsByLabel.get(i)) {
            labels.set(vertex, i);
        }
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Check if the buckets are not null and the labels are not null
    if (bucketsByLabel == null || labels == null || labels.size() < bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid input!");
    }

    // Traverse from the last bucket to the first bucket
    for (int i = bucketsByLabel.size() - 1; i >= 0; i--) {
        // Check if the current bucket is not empty and its label is greater than or equal to minLabel
        if (!bucketsByLabel.get(i).isEmpty() && bucketsByLabel.get(i).iterator().next() >= minLabel) {
            // Move the vertices from the current bucket to the bucket with label 0
            bucketsByLabel.get(0).addAll(bucketsByLabel.get(i));

            // Clear the current bucket
            bucketsByLabel.get(i).clear();
        }
    }

    // Update the labeling
    labels.forEach(label -> {
        if (label > minLabel) {
            label = label - minLabel;
        } else {
            label = label;
        }
    });
}

private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel) {
    // Initialize an empty set for bucket with label 0
    Set<Integer> bucket0 = new HashSet<>();

    // Initialize a boolean flag to track if any vertex is moved from bucket with label minLabel
    boolean movedVertices = false;

    // Iterate over the list of buckets to process each bucket
    for (int currLabel = 0; currLabel < bucketsByLabel.size(); currLabel++) {
        if (currLabel == minLabel) {
            // If the current label is minLabel, move all vertices to bucket 0
            bucket0.addAll(bucketsByLabel.get(currLabel));
            // Clear the bucket with label minLabel
            bucketsByLabel.set(currLabel, new HashSet<>());
            // Flag the vertices have been moved
            movedVertices = true;
        } else {
            // If the current label is not minLabel, add vertices to the new bucket or clear the current bucket
            for (Integer vertex : bucketsByLabel.get(currLabel)) {
                if (vertex > currLabel) {
                    bucket0.add(vertex);
                } else {
                    bucketsByLabel.get(currLabel).clear();
                }
            }
        }
    }

    // If any vertices were moved from minLabel to bucket 0, update the labels
    if (movedVertices) {
        for (int i = 0; i < labels.size(); i++) {
            if (labels.get(i) == minLabel) {
                labels.set(i, 0);
            }
        }
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || bucketsByLabel.isEmpty() || labels.isEmpty()) {
        throw new IllegalArgumentException("Bucket labels and buckets must not be null or empty.");
    }

    // Check if the bucket containing minLabel is non-empty and remove it from its current location
    if (!bucketsByLabel.get(minLabel).isEmpty()) {
        Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
        int minLabelVertex = minLabelBucket.iterator().next();
        labels.set(minLabelVertex, 0);
        minLabelBucket.remove(minLabelVertex);

        // Add all vertices with label 0 from the bucket with label 0 to the bucket with label minLabel
        Set<Integer> bucket0 = bucketsByLabel.get(0);
        bucket0.addAll(bucketsByLabel.get(minLabel));
        bucketsByLabel.remove(minLabel);
    } else {
        // If the bucket containing minLabel is already empty, skip the reload operation
        return;
    }
}

