public boolean isCompatible(DataTable dataset) {
    // Check if dataset is null
    if (dataset == null) {
        throw new IllegalArgumentException("DataTable cannot be null");
    }

    // Initialize result variable
    boolean isCompatible = true;

    // Iterate over each column in the dataset
    for (column in dataset.getColumns()) {
        // Check if column is null
        if (column == null) {
            throw new IllegalArgumentException("Column cannot be null");
        }

        // Get the column type
        DataColumnType type = dataset.getColumnType(column);

        // Iterate over each row in the column
        for (row in column.getRows()) {
            // Check if row is null
            if (row == null) {
                throw new IllegalArgumentException("Row cannot be null");
            }

            // Get the row value
            Object value = row.getValue();

            // Check if value is null
            if (value == null) {
                throw new IllegalStateException("Value in row cannot be null");
            }

            // Compare the value with the current column type
            switch (type) {
                case BOOLEAN:
                    isCompatible = isCompatible && ((Boolean) value).equals(column.getBooleanValue());
                    break;
                case INTEGER:
                    isCompatible = isCompatible && ((Integer) value).equals(column.getIntegerValue());
                    break;
                case REAL:
                    isCompatible = isCompatible && ((Double) value).equals(column.getDoubleValue());
                    break;
                case STRING:
                    isCompatible = isCompatible && ((String) value).equals(column.getStringValue());
                    break;
                case DATE_TIME:
                    isCompatible = isCompatible && ((DateTime) value).equals(column.getDateTimeValue());
                    break;
                default:
                    throw new UnsupportedOperationException("Unsupported column type: " + type);
            }

            // If incompatible, set flag and break loop
            if (!isCompatible) {
                break;
            }
        }

        // If incompatible, set flag and break loop
        if (!isCompatible) {
            break;
        }
    }

    return isCompatible;
}

