    int n = s.length() / 4 + (s.length() % 4 == 0 ? 0 : 1);
    StringBuilder b = new StringBuilder(n);

    while (i <= j) {
        if (i == j && s.charAt(i) == '=') {
            break;
        }

        int r = i >> 2;
        int g = (i & 3) << 2 | (s.charAt(i + 1) & 0xf0) >> 4;
        int b = (i & 3) << 4 | (s.charAt(i + 2) & 0xf0) >> 4;
        int a = (i & 3) << 4 | (s.charAt(i + 3) & 0xf0) >> 4;

        b.append((char) (r));
        b.append((char) (g));
        b.append((char) (b));
        b.append((char) (a));

        i += 4;
        j -= 4;
    }

    String result = b.toString();
    return result;
}

