    if (buf == null) {
        throw new IllegalArgumentException("Buffer must not be null");
    }

    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid name start index");
    }

    int end = buf.indexOf(' ', nameStart);
    if (end == -1) {
        end = buf.length();
    }

    int abbrevLen = end - nameStart;
    buf.setLength(end - abbrevLen);
    buf.append("*").append(abbrevLen).append("*");
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("nameStart out of bounds");
    }
    int length = buf.length();
    int end = Math.min(length, nameStart + 3); // abbreviate the first 3 characters
    for (int i = nameStart; i < end; i++) {
        buf.setCharAt(i, '*');
    }
}

