private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices cannot be null");
    }
    if (vertices.isEmpty()) {
        return true; // An empty set is considered a clique
    }

    V firstVertex = vertices.iterator().next();

    for (E edge : graph.edgesOf(firstVertex)) {
        V vertex2 = edge.target();
        if (!vertices.contains(vertex2)) {
            return false; // Vertex is only connected to one of the vertices in the set
        }
    }
    // If the condition holds, all vertices are connected to each other, so it's a clique
    return true;
}

private static <V,E>boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || graph.size() < vertices.size()) {
        // Invalid input: empty graph or not enough vertices for clique definition
        return false;
    }

    Set<V> remainingVertices = graph.vertices();
    remainingVertices.removeAll(vertices);

    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1.equals(vertex2)) {
                continue;
            }
            if (!graph.containsEdge(vertex1, vertex2)) {
                // Not all vertices in the set of vertices are connected with each other
                return false;
            }
        }
    }

    // All vertices in the set of vertices are connected with each other, and no isolated vertices remain
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || graph.isEmpty() || vertices.size() > graph.vertexCount()) {
        throw new IllegalArgumentException("Invalid input parameters.");
    }

    for (V vertex : vertices) {
        if (!graph.hasVertex(vertex)) {
            throw new IllegalArgumentException("Vertex not in the graph.");
        }
    }

    boolean[] isVertexInClique = new boolean[vertices.size()];
    Arrays.fill(isVertexInClique, true);

    for (V vertex : vertices) {
        Set<E> neighbors = graph.outgoingEdgesOf(vertex);
        for (E edge : neighbors) {
            V neighbor = graph.end(vertices, edge);
            if (vertices.contains(neighbor)) {
                isVertexInClique[indexOf(vertices, neighbor)] = false;
            }
        }
    }

    return new HashSet<>(Arrays.asList(isVertexInClique)).size() == vertices.size();
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    Set<E> edges = graph.edgesOf(vertices, false);

    for (E edge : edges) {
        V source = graph.source(edge);
        V target = graph.target(edge);

        boolean isSourceVertexInVertices = vertices.contains(source);
        boolean isTargetVertexInVertices = vertices.contains(target);

        if (!isSourceVertexInVertices || !isTargetVertexInVertices) {
            return false;
        }
    }

    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if(vertices == null || vertices.isEmpty()) return true;

    // First check if every vertex in the subgraph is connected to all other vertices
    for(V v : vertices) {
        Set<V> adjacent = graph.getAdjacentVertices(v);
        if(adjacent.isEmpty() || adjacent.size() < vertices.size()) return false;
    }

    // Now check if the subgraph induced by vertices forms a clique
    for(V v : vertices) {
        Graph<V,E> subgraph = new Graph<>();
        for(V w : vertices) {
            if(v != w) subgraph.addEdge(v, w);
        }

        if(!isClique(subgraph, subgraph.vertices())) return false;
    }

    return true;
}

