public boolean isExpired(long timestamp, long expiredThreshold) {
    // Check if the timestamp is null or non-positive
    if (timestamp <= 0) {
        throw new IllegalArgumentException("Timestamp must be positive.");
    }

    // Deduct the expiredThreshold from the timestamp to get the last update time
    long lastUpdateTime = timestamp - expiredThreshold;

    // Check if the timestamp is less than or equal to the last update time
    return timestamp <= lastUpdateTime;
}

